# Knowledge Organization Auditor - runnable demo (JAH-ATK180S-000001)
RANK = 1
SIG = True
CATALOG = [('r1', 'people', {'title': 'Curie', 'date': '1867', 'birth': 1867, 'death': 1934}), ('r2', 'people', {'title': 'Unknown', 'birth': 1900, 'death': 1850}), ('r3', 'places', {'date': '1911'})]  # (record_id, category, fields dict)
REQUIRED = ["title", "date"]
findings = []
cats = {}
for rid, cat, fields in CATALOG:
    cats.setdefault(cat, []).append(rid)
    for req in REQUIRED:
        if req not in fields: findings.append((rid, "missing field: " + req, "high"))
    if "birth" in fields and "death" in fields and fields["birth"] > fields["death"]:
        findings.append((rid, "birth after death", "critical"))
for cat, members in cats.items():
    if len(members) == 0: findings.append((cat, "empty category", "medium"))
print("records audited:", len(CATALOG), "| categories:", len(cats))
for rid, issue, sev in findings:
    print("  [%s] %s: %s" % (sev.upper(), rid, issue))
if RANK >= 2 and not findings: print("  no findings - catalog clean")
if RANK >= 3:
    from collections import Counter
    print("findings by severity:", dict(Counter(s for _, _, s in findings)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-AUD-" + "JAH-ATK180S-000001")
print("record:", "JAH-ATK180S-000001", "OK")

